package com.meshcrossway.android;

import android.app.*;
import android.content.*;
import android.location.Location;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.maplibre.android.MapLibre;
import org.maplibre.android.maps.*;
import org.maplibre.android.camera.*;
import org.maplibre.android.geometry.*;
import org.maplibre.android.style.sources.*;
import org.maplibre.android.style.layers.*;
import org.maplibre.geojson.*;
import static org.maplibre.android.style.layers.PropertyFactory.*;
import static org.maplibre.android.style.expressions.Expression.*;
import static com.meshcrossway.android.MeshData.*;

/** One local visualization of two explicitly identified independent networks. */
final class MapPanel {
    static final int MT=0xffff8a24,MC=0xff6cbde6,LOCAL=0xff72d8a5;
    static final class Located {RadioProfile profile;String radio;Node node;boolean favorite;Located(RadioProfile p,String r,Node n,boolean f){profile=p;radio=r;node=n;favorite=f;}}
    interface Host {List<Located> nodes();List<Poi> pois();Location phone();boolean gpsEnabled();void gps();void node(Located node);void poi(String name,double lat,double lon);void deletePoi(String id);}
    private final Activity activity;private final Host host;private final SharedPreferences preferences;final MapView mapView;final LinearLayout root;final OfflineMaps offline;
    MapLibreMap map;boolean styleReady;int markerCount;private int network;private boolean favorites,recent,labels=true,started,resumed,destroyed,fallback,autoFit,centerPhone;
    private final TextView status,downloadStatus;private final String override;private LatLng focus;private List<Located> shown=new ArrayList<>();
    private static final String BLANK="{\"version\":8,\"sources\":{},\"layers\":[{\"id\":\"background\",\"type\":\"background\",\"paint\":{\"background-color\":\"#111820\"}}]}";
    MapPanel(Activity activity,Host host,String styleOverride,LatLng requestedFocus){
        this.activity=activity;this.host=host;override=styleOverride;focus=requestedFocus;preferences=activity.getSharedPreferences("map",Context.MODE_PRIVATE);network=preferences.getInt("network",0);favorites=preferences.getBoolean("favorites",false);recent=preferences.getBoolean("recent",false);labels=preferences.getBoolean("labels",true);
        offline=MapEngine.init(activity);root=new LinearLayout(activity);root.setOrientation(LinearLayout.HORIZONTAL);root.setBackgroundColor(0xff090c10);
        ScrollView railScroll=new ScrollView(activity);LinearLayout rail=new LinearLayout(activity);rail.setOrientation(LinearLayout.VERTICAL);rail.setPadding(dp(5),dp(8),dp(5),dp(8));rail.setBackgroundColor(0xff181d24);railScroll.addView(rail);root.addView(railScroll,new LinearLayout.LayoutParams(dp(70),-1));
        control(rail,"Layers",this::layers);control(rail,"Zoom +",()->{if(map!=null)map.animateCamera(CameraUpdateFactory.zoomIn());});control(rail,"Zoom −",()->{if(map!=null)map.animateCamera(CameraUpdateFactory.zoomOut());});control(rail,"GPS",()->{centerPhone=true;host.gps();update();});control(rail,"Fit nodes",this::fit);control(rail,"POIs",this::pois);control(rail,"Offline",this::offlineDialog);control(rail,"North",()->{if(map!=null)map.resetNorth();});
        LinearLayout content=new LinearLayout(activity);content.setOrientation(LinearLayout.VERTICAL);root.addView(content,new LinearLayout.LayoutParams(0,-1,1));status=label("Loading map…",12);status.setPadding(dp(8),dp(6),dp(8),dp(6));content.addView(status);
        mapView=new MapView(activity);mapView.onCreate(null);mapView.setMaximumFps(30);content.addView(mapView,new LinearLayout.LayoutParams(-1,0,1));
        downloadStatus=label("",11);content.addView(downloadStatus);TextView attribution=label("© OpenMapTiles · © OpenStreetMap contributors · OpenFreeMap",10);attribution.setPadding(dp(5),dp(4),dp(5),dp(4));attribution.setOnClickListener(v->activity.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://openfreemap.org/"))));content.addView(attribution);
        offline.listener=this::updateDownloads;updateDownloads();
        mapView.addOnDidFailLoadingMapListener(error->{if(!destroyed&&!styleReady&&!fallback&&map!=null){fallback=true;map.setStyle(new Style.Builder().fromJson(BLANK),this::install);status.setText("Basemap unavailable • nodes only. Use a saved area or enable internet.");}});
        mapView.getMapAsync(ready->{if(destroyed)return;map=ready;map.getUiSettings().setAttributionEnabled(false);map.getUiSettings().setLogoEnabled(false);map.setPrefetchZoomDelta(0);map.setMaxZoomPreference(19);map.setMinZoomPreference(1);
            double lat=Double.parseDouble(preferences.getString("lat","0")),lon=Double.parseDouble(preferences.getString("lon","0")),zoom=Double.parseDouble(preferences.getString("zoom","2"));autoFit=!preferences.contains("lat")&&focus==null;
            map.moveCamera(CameraUpdateFactory.newLatLngZoom(focus!=null?focus:new LatLng(lat,lon),focus!=null?14:zoom));
            map.addOnCameraMoveStartedListener(reason->{if(reason==1)autoFit=false;});map.addOnMapClickListener(this::tap);map.addOnMapLongClickListener(point->{newPoi(point);return true;});loadStyle();
        });
    }
    private int dp(int value){return Math.round(value*activity.getResources().getDisplayMetrics().density);}
    private TextView label(String text,int size){TextView view=new TextView(activity);view.setText(text);view.setTextSize(size);view.setTextColor(0xfff2f4f7);return view;}
    private void control(LinearLayout parent,String name,Runnable action){Button button=new Button(activity);button.setAllCaps(false);button.setText(name);button.setTextColor(MT);button.setTextSize(11);button.setPadding(0,0,0,0);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.bottomMargin=dp(5);parent.addView(button,p);button.setOnClickListener(v->action.run());}
    private String styleUrl(){return override!=null?override:preferences.getBoolean("light",false)?MapEngine.LIGHT:MapEngine.DARK;}
    private void loadStyle(){if(map==null||destroyed)return;styleReady=false;fallback=false;MapLibre.setConnected(preferences.getBoolean("offline",false)?Boolean.FALSE:null);map.setStyle(new Style.Builder().fromUri(styleUrl()),this::install);}
    private void install(Style style){if(destroyed)return;
        style.addSource(new GeoJsonSource("mesh-nodes",FeatureCollection.fromFeatures(new ArrayList<>()),new GeoJsonOptions().withCluster(true).withClusterRadius(45).withClusterMaxZoom(12)));
        style.addLayer(new CircleLayer("mesh-clusters","mesh-nodes").withFilter(has("point_count")).withProperties(circleColor(0xff7b7393),circleRadius(16f),circleStrokeColor(0xfff2f4f7),circleStrokeWidth(1f)));
        style.addLayer(new CircleLayer("mesh-points","mesh-nodes").withFilter(not(has("point_count"))).withProperties(circleColor(match(get("network"),literal("MESHTASTIC"),color(MT),color(MC))),circleRadius(7f),circleStrokeColor(0xfff2f4f7),circleStrokeWidth(switchCase(eq(get("favorite"),true),literal(3),literal(1)))));
        style.addSource(new GeoJsonSource("local-pois",FeatureCollection.fromFeatures(new ArrayList<>())));style.addLayer(new CircleLayer("poi-points","local-pois").withProperties(circleColor(LOCAL),circleRadius(7f),circleStrokeColor(0xfff2f4f7),circleStrokeWidth(1f)));
        style.addSource(new GeoJsonSource("phone",FeatureCollection.fromFeatures(new ArrayList<>())));style.addLayer(new CircleLayer("phone-point","phone").withProperties(circleColor(0xff589dff),circleRadius(7f),circleStrokeColor(0xffffffff),circleStrokeWidth(3f)));
        style.addSource(new GeoJsonSource("area-preview",FeatureCollection.fromFeatures(new ArrayList<>())));style.addLayer(new LineLayer("area-outline","area-preview").withProperties(lineColor(MT),lineWidth(3f)));
        if(override==null&&!fallback){style.addLayer(new SymbolLayer("cluster-count","mesh-nodes").withFilter(has("point_count")).withProperties(textField(org.maplibre.android.style.expressions.Expression.toString(get("point_count"))),textSize(12f),textColor(0xffffffff),textFont(new String[]{"Noto Sans Regular"})));SymbolLayer names=new SymbolLayer("mesh-labels","mesh-nodes").withFilter(not(has("point_count"))).withProperties(textField(get("label")),textSize(13f),textColor(0xfff2f4f7),textHaloColor(0xff090c10),textHaloWidth(1.5f),textOffset(new Float[]{0f,1.2f}),textFont(new String[]{"Noto Sans Regular"}));names.setMinZoom(11);style.addLayer(names);}
        styleReady=true;update();
    }
    void update(){if(destroyed||map==null||!styleReady)return;Style style=map.getStyle();if(style==null)return;shown=new ArrayList<>();ArrayList<Feature> points=new ArrayList<>();int mt=0,mc=0;
        for(Located ref:host.nodes()){Node n=ref.node;if(!n.position||!GeoMath.valid(n.lat,n.lon)||(network!=0&&network!=ref.profile.ordinal()+1)||(favorites&&!ref.favorite)||(recent&&System.currentTimeMillis()/1000-n.heard>86400))continue;shown.add(ref);Feature f=Feature.fromGeometry(Point.fromLngLat(n.lon,n.lat));f.addStringProperty("network",ref.profile.name());f.addStringProperty("radio",ref.radio);f.addStringProperty("node",n.id);f.addBooleanProperty("favorite",ref.favorite);String shortId=ref.profile==RadioProfile.MESHTASTIC?String.format(Locale.ROOT,"%04x",Long.parseLong(n.id)&65535):n.id.substring(0,Math.min(4,n.id.length()));f.addStringProperty("label",(ref.profile==RadioProfile.MESHTASTIC?"MT ":"MC ")+shortId);points.add(f);if(ref.profile==RadioProfile.MESHTASTIC)mt++;else mc++;}
        markerCount=points.size();((GeoJsonSource)style.getSource("mesh-nodes")).setGeoJson(FeatureCollection.fromFeatures(points));ArrayList<Feature> pois=new ArrayList<>();for(Poi p:host.pois()){Feature f=Feature.fromGeometry(Point.fromLngLat(p.lon,p.lat));f.addStringProperty("poi",p.id);pois.add(f);}((GeoJsonSource)style.getSource("local-pois")).setGeoJson(FeatureCollection.fromFeatures(pois));
        Location phone=host.gpsEnabled()?host.phone():null;ArrayList<Feature> location=new ArrayList<>();String gps="phone GPS off";if(phone!=null){location.add(Feature.fromGeometry(Point.fromLngLat(phone.getLongitude(),phone.getLatitude())));long age=Math.max(0,(System.currentTimeMillis()-phone.getTime())/1000);gps="GPS ±"+Math.round(phone.getAccuracy())+"m"+(age>30?" · "+age+"s old":"");if(centerPhone){map.animateCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(phone.getLatitude(),phone.getLongitude()),15));centerPhone=false;autoFit=false;}}
        ((GeoJsonSource)style.getSource("phone")).setGeoJson(FeatureCollection.fromFeatures(location));Layer names=style.getLayer("mesh-labels");if(names!=null)names.setProperties(visibility(labels?"visible":"none"));status.setText((fallback?"Nodes only · ":"")+"MT "+mt+" · MC "+mc+" · "+gps);if(autoFit&&!shown.isEmpty()){autoFit=false;fit();}
    }
    private boolean tap(LatLng point){if(!styleReady)return false;List<Feature> features=map.queryRenderedFeatures(map.getProjection().toScreenLocation(point),"mesh-points","mesh-clusters","poi-points");if(features.isEmpty())return false;Feature f=features.get(0);if(f.hasProperty("point_count")){map.animateCamera(CameraUpdateFactory.newLatLngZoom(point,map.getCameraPosition().zoom+2));return true;}if(f.hasProperty("poi")){for(Poi p:host.pois())if(p.id.equals(f.getStringProperty("poi"))){poiDetails(p);return true;}}if(!f.hasProperty("node"))return false;for(Located ref:shown)if(ref.node.id.equals(f.getStringProperty("node"))&&ref.profile.name().equals(f.getStringProperty("network"))&&ref.radio.equals(f.getStringProperty("radio"))){host.node(ref);return true;}return false;}
    private void fit(){if(map==null||destroyed)return;if(mapView.getWidth()==0||mapView.getHeight()==0){mapView.post(this::fit);return;}if(shown.isEmpty()){Toast.makeText(activity,"No nodes with a reported position in these layers",Toast.LENGTH_SHORT).show();return;}LatLngBounds.Builder bounds=new LatLngBounds.Builder();for(Located ref:shown)bounds.include(new LatLng(ref.node.lat,ref.node.lon));if(shown.size()==1)map.animateCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(shown.get(0).node.lat,shown.get(0).node.lon),14));else map.animateCamera(CameraUpdateFactory.newLatLngBounds(bounds.build(),dp(30)));}
    void center(double lat,double lon){if(map!=null){autoFit=false;map.animateCamera(CameraUpdateFactory.newLatLngZoom(new LatLng(lat,lon),14));}}
    private void layers(){LinearLayout options=new LinearLayout(activity);options.setOrientation(LinearLayout.VERTICAL);options.setPadding(dp(16),dp(8),dp(16),dp(8));RadioGroup group=new RadioGroup(activity);String[] names={"Both networks","Meshtastic","MeshCore"};for(int i=0;i<3;i++){RadioButton b=new RadioButton(activity);b.setId(100+i);b.setText(names[i]);group.addView(b);}group.check(100+network);options.addView(group);CheckBox favorite=new CheckBox(activity);favorite.setText("Favorites only");favorite.setChecked(favorites);options.addView(favorite);CheckBox fresh=new CheckBox(activity);fresh.setText("Heard in the last 24 hours");fresh.setChecked(recent);options.addView(fresh);CheckBox text=new CheckBox(activity);text.setText("Node labels");text.setChecked(labels);options.addView(text);CheckBox light=new CheckBox(activity);light.setText("Light basemap");light.setChecked(preferences.getBoolean("light",false));options.addView(light);CheckBox offlineMode=new CheckBox(activity);offlineMode.setText("Offline mode (saved map data only)");offlineMode.setChecked(preferences.getBoolean("offline",false));options.addView(offlineMode);new AlertDialog.Builder(activity).setTitle("Map layers").setView(options).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{boolean reload=light.isChecked()!=preferences.getBoolean("light",false)||offlineMode.isChecked()!=preferences.getBoolean("offline",false);network=group.getCheckedRadioButtonId()-100;favorites=favorite.isChecked();recent=fresh.isChecked();labels=text.isChecked();preferences.edit().putInt("network",network).putBoolean("favorites",favorites).putBoolean("recent",recent).putBoolean("labels",labels).putBoolean("light",light.isChecked()).putBoolean("offline",offlineMode.isChecked()).apply();if(reload)loadStyle();else update();}).show();}
    private void newPoi(LatLng point){EditText name=new EditText(activity);name.setHint("Point name");new AlertDialog.Builder(activity).setTitle("Save local POI").setMessage("Saved on this phone. It is not broadcast to either network.").setView(name).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->host.poi(name.getText().toString(),point.getLatitude(),point.getLongitude())).show();}
    private void pois(){List<Poi> entries=new ArrayList<>(host.pois());String[] names=new String[entries.size()+1];names[0]="Add at map center";for(int i=1;i<names.length;i++)names[i]=entries.get(i-1).name;new AlertDialog.Builder(activity).setTitle("Local points of interest").setItems(names,(d,index)->{if(index==0&&map!=null)newPoi(map.getCameraPosition().target);else if(index>0)poiDetails(entries.get(index-1));}).setNegativeButton("Close",null).show();}
    private void poiDetails(Poi p){new AlertDialog.Builder(activity).setTitle(p.name).setMessage(String.format(Locale.ROOT,"%.6f, %.6f\nLocal to this phone",p.lat,p.lon)).setPositiveButton("Show on map",(d,w)->center(p.lat,p.lon)).setNeutralButton("Delete",(d,w)->new AlertDialog.Builder(activity).setTitle("Delete local POI?").setPositiveButton("Delete",(a,b)->host.deletePoi(p.id)).setNegativeButton("Cancel",null).show()).setNegativeButton("Close",null).show();}
    private void updateDownloads(){if(destroyed)return;String message=offline.error;for(OfflineMaps.Area a:offline.areas)if(offline.active(a))message=a.name+" · "+a.status;downloadStatus.setText(message);downloadStatus.setVisibility(message.isEmpty()?View.GONE:View.VISIBLE);}
    private void offlineDialog(){List<OfflineMaps.Area> entries=new ArrayList<>(offline.areas);ArrayList<String> names=new ArrayList<>();names.add("Download the visible area…");for(OfflineMaps.Area a:entries)names.add(a.name+" · "+a.status);new AlertDialog.Builder(activity).setTitle("Offline areas").setItems(names.toArray(new String[0]),(d,index)->{if(index==0)downloadDialog();else areaActions(entries.get(index-1));}).setNegativeButton("Close",null).show();}
    private void downloadDialog(){if(map==null||!styleReady)return;LatLngBounds bounds=map.getProjection().getVisibleRegion().latLngBounds;LinearLayout options=new LinearLayout(activity);options.setOrientation(LinearLayout.VERTICAL);options.setPadding(dp(16),0,dp(16),0);TextView instructions=label("Pan and zoom the map first to select the area. Downloads pause when the app goes into the background.",13);options.addView(instructions);EditText name=new EditText(activity);name.setHint("Area name");options.addView(name);SeekBar zoom=new SeekBar(activity);zoom.setMax(7);zoom.setProgress(5);options.addView(zoom);TextView estimate=label("",13);options.addView(estimate);Runnable update=()->{int z=zoom.getProgress()+8;long tiles=GeoMath.tileEstimate(bounds.getLatSouth(),bounds.getLonWest(),bounds.getLatNorth(),bounds.getLonEast(),z);estimate.setText("Detail zoom "+z+" · "+(tiles>GeoMath.MAX_TILES?"area too large":tiles+" estimated tiles")+"\nLimit: 2,400 estimated / 2,800 actual tiles and 45 MB.");};zoom.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){update.run();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});update.run();new AlertDialog.Builder(activity).setTitle("Download selected area").setView(options).setNegativeButton("Cancel",null).setPositiveButton("Download",(d,w)->{preferences.edit().putBoolean("offline",false).apply();MapLibre.setConnected(null);offline.create(name.getText().toString(),styleUrl(),bounds,zoom.getProgress()+8,mapView.getPixelRatio());}).show();}
    private void areaActions(OfflineMaps.Area area){new AlertDialog.Builder(activity).setTitle(area.name).setMessage(area.status).setPositiveButton("View bounds",(d,w)->{if(map!=null&&area.region.getDefinition() instanceof org.maplibre.android.offline.OfflineTilePyramidRegionDefinition){org.maplibre.android.offline.OfflineTilePyramidRegionDefinition def=(org.maplibre.android.offline.OfflineTilePyramidRegionDefinition)area.region.getDefinition();LatLngBounds b=def.getBounds();map.animateCamera(CameraUpdateFactory.newLatLngBounds(b,dp(20)));ArrayList<Point> ring=new ArrayList<>();ring.add(Point.fromLngLat(b.getLonWest(),b.getLatSouth()));ring.add(Point.fromLngLat(b.getLonEast(),b.getLatSouth()));ring.add(Point.fromLngLat(b.getLonEast(),b.getLatNorth()));ring.add(Point.fromLngLat(b.getLonWest(),b.getLatNorth()));ring.add(ring.get(0));if(styleReady)((GeoJsonSource)map.getStyle().getSource("area-preview")).setGeoJson(Feature.fromGeometry(LineString.fromLngLats(ring)));}}).setNeutralButton(offline.active(area)?"Pause":"Resume",(d,w)->{MapLibre.setConnected(null);preferences.edit().putBoolean("offline",false).apply();if(offline.active(area))offline.pause();else offline.start(area);}).setNegativeButton("Delete…",(d,w)->new AlertDialog.Builder(activity).setTitle("Delete downloaded area?").setMessage("Shared tiles needed by other areas may be retained.").setPositiveButton("Delete",(a,b)->offline.delete(area)).setNegativeButton("Cancel",null).show()).show();}
    void onStart(){if(!started&&!destroyed){mapView.onStart();started=true;}}
    void onResume(){onStart();if(!resumed&&!destroyed){mapView.onResume();resumed=true;}}
    void onPause(){if(resumed&&!destroyed){mapView.onPause();resumed=false;}}
    void onStop(){onPause();if(started&&!destroyed){mapView.onStop();started=false;}offline.pause();}
    void destroy(){if(destroyed)return;if(map!=null){CameraPosition c=map.getCameraPosition();preferences.edit().putString("lat",Double.toString(c.target.getLatitude())).putString("lon",Double.toString(c.target.getLongitude())).putString("zoom",Double.toString(c.zoom)).apply();}onPause();if(started){mapView.onStop();started=false;}offline.listener=null;mapView.onDestroy();destroyed=true;}
}
